"""The README's results block, generated by ``pii-guard eval report`` (LAB-1239).

The README's compact leak table used to be copied by hand from ``docs/benchmarks.md`` and went
stale whenever a new run landed. Now ``pii-guard eval report`` rewrites the text between
:data:`START` and :data:`END` in ``README.md`` and ``--check`` fails when it is out of date.

What goes in the table is editorial, so it lives in the ``readme`` section of
``docs/benchmarks/config.json``; the numbers come from the same index and per-dataset counts
as ``docs/benchmarks.md``, rounded the same way::

    "readme": {
      "columns": [
        {"title": "Hand-written", "fixture_set": "smoke"},
        {"title": "Agent traffic", "dataset": "agent-traffic"}
      ],
      "rows": [
        {"system": "rules+ner:xlmr-base-v2-hn", "label": "**PII Guard fast**", "short": "fast",
         "marks": {"agent-traffic": "†"}},
        {"system": "rules", "label": "PII Guard rules only", "p50": false}
      ]
    }

A column reads either the latest snapshot of a fixture set (its pooled ``all`` leak) or the
latest per-dataset counts of a registered dataset (``eval/datasets/results/``). The lowest
leak in a column is bold, unless the best cell carries a caveat mark (an in-distribution
result is not a win). The block also says the hand-written set's detection p50 per row, the
first row's over-masking per column (LAB-1598: it used to be hand-copied prose under the
table, and went stale) and links the records behind the first row.

LAB-1656 options, each off unless set in the ``readme`` section:

- ``"over_masking_table": true``: an over-masking table for every row and column (lowest in
  bold) in place of the first row's one-line summary, so a low leak bought by masking
  everything shows up next to it;
- ``"per_language": true``: the first row's leak per language on the headline set;
- ``"latency": {"run": "<run id>", "concurrency": 1, "stream": false, "label": "..."}``: one
  gateway-overhead figure (p50 and p95) from a ``pii-guard bench latency`` record, so the
  README states a single, sourced latency number instead of hand-copied ones;
- ``"model_latency": {"file": "<repo path>", "model": "<name>", "label": "..."}``: the same,
  from a model-latency measurement (``training/ner/eval_v3.py latency`` JSON: the NER
  detector's own time per message, no gateway or rules) when no clean gateway record exists.
  ``pii-guard eval report`` reads the file and passes it in as ``data``.

LAB-1663, ``"layout": "compact"``: one table that fits GitHub's column at 1280 px, a row per
fixture set (``columns``) and a column per system (``rows``), each cell ``leak · over-masking``.
Under it come the ``notes`` lines, a ``caveats`` list and a collapsed ``details`` block (the
records behind the first system, the model latency). An ``intro`` section also generates the
README's first-screen block between :data:`INTRO_START` and :data:`INTRO_END`: the pitch
bullets and the hero image. Prose lives in the config; numbers enter it only through
placeholders filled from the records (:func:`fill`): ``{leak:<set>:<system>}``,
``{over:...}``, ``{partial:...}`` (one-decimal percentages), ``{docs:<set>}`` (documents) and
``{langs:<set>}`` / ``{codes:<set>}`` (its languages); a system is a run-record key or an
alias from ``aliases``.

A fixture-set cell whose snapshot is missing some of the set's languages (a tool run on an
earlier fixture version, say) is marked ``§`` and explained under the table, never silently
pooled with the complete rows; a marked best cell is not bold.
"""

from __future__ import annotations

import re
from collections.abc import Mapping, Sequence
from typing import Any

from pii_guard.eval.record import RecordError
from pii_guard.eval.stats import fmt_duration

__all__ = [
    "END",
    "INTRO_END",
    "INTRO_START",
    "START",
    "fill",
    "parse_spec",
    "render_block",
    "render_compact",
    "render_intro",
    "render_readme",
    "splice",
]

START = "<!-- results:start -->"
END = "<!-- results:end -->"
INTRO_START = "<!-- intro:start -->"
INTRO_END = "<!-- intro:end -->"
_NOTE = (
    "<!-- Generated by `pii-guard eval report` from the run records and the `readme` section "
    "of docs/benchmarks/config.json; edit those, not this block. -->"
)
_MISSING = "—"
_PARTIAL = "§"


def parse_spec(raw: object, where: str) -> dict[str, Any]:
    """Validate the config's ``readme`` section; :class:`RecordError` names what is wrong."""
    if not isinstance(raw, dict):
        raise RecordError(f"{where}: 'readme' must be an object")
    columns, rows = raw.get("columns"), raw.get("rows")
    if not isinstance(columns, list) or not columns or not isinstance(rows, list) or not rows:
        raise RecordError(f"{where}: 'readme' needs non-empty 'columns' and 'rows' lists")
    for col in columns:
        if (
            not isinstance(col, dict)
            or not isinstance(col.get("title"), str)
            or (("fixture_set" in col) == ("dataset" in col))
        ):
            raise RecordError(
                f"{where}: each readme column needs a 'title' and one of 'fixture_set' or "
                f"'dataset': {col!r}"
            )
    for row in rows:
        if not isinstance(row, dict) or not all(
            isinstance(row.get(k), str) for k in ("system", "label")
        ):
            raise RecordError(f"{where}: each readme row needs 'system' and 'label': {row!r}")
    spec: dict[str, Any] = {"columns": columns, "rows": rows}
    for key in ("layout", "aliases", "intro", "notes", "caveats", "details"):
        if key in raw:
            spec[key] = raw[key]
    if spec.get("layout", "wide") not in ("wide", "compact"):
        raise RecordError(f"{where}: readme 'layout' must be 'wide' or 'compact'")
    for key in ("notes", "caveats"):
        if key in spec and not (
            isinstance(spec[key], list) and all(isinstance(x, str) for x in spec[key])
        ):
            raise RecordError(f"{where}: readme '{key}' must be a list of strings")
    intro = spec.get("intro")
    if intro is not None and (
        not isinstance(intro, dict)
        or not isinstance(intro.get("bullets"), list)
        or not all(isinstance(intro.get(k), str) for k in ("image", "alt", "caption"))
    ):
        raise RecordError(f"{where}: readme 'intro' needs 'bullets', 'image', 'alt', 'caption'")
    for flag in ("over_masking_table", "per_language"):
        if flag in raw:
            if not isinstance(raw[flag], bool):
                raise RecordError(f"{where}: readme '{flag}' must be true or false")
            spec[flag] = raw[flag]
    if "latency" in raw:
        lat = raw["latency"]
        if (
            not isinstance(lat, dict)
            or not isinstance(lat.get("run"), str)
            or not isinstance(lat.get("label"), str)
            or not isinstance(lat.get("concurrency", 1), int)
            or not isinstance(lat.get("stream", False), bool)
        ):
            raise RecordError(
                f"{where}: readme 'latency' needs 'run' and 'label' strings, an integer "
                f"'concurrency' and a boolean 'stream': {lat!r}"
            )
        spec["latency"] = lat
    if "model_latency" in raw:
        ml = raw["model_latency"]
        if not isinstance(ml, dict) or not all(
            isinstance(ml.get(k), str) for k in ("file", "model", "label")
        ):
            raise RecordError(
                f"{where}: readme 'model_latency' needs 'file', 'model' and 'label' strings: {ml!r}"
            )
        spec["model_latency"] = dict(ml)
    return spec


def _model_latency_line(ml: Mapping[str, Any], where: str) -> str:
    data = ml.get("data")
    if not isinstance(data, Mapping):
        raise RecordError(f"{where}: model_latency {ml['file']!r} was not read")
    result = data.get("results", {}).get(ml["model"])
    if not isinstance(result, Mapping):
        raise RecordError(f"{where}: model_latency {ml['file']!r} has no result {ml['model']!r}")
    return (
        f"{ml['label']}: p50 {fmt_duration(result['p50_ms'])}, "
        f"p95 {fmt_duration(result['p95_ms'])} ({data['messages']} messages of about "
        f"{round(data['mean_chars'])} characters, {data['machine']}, "
        f"{data['torch_threads']} threads; [measurement]({ml['file']}))."
    )


def _latency_line(index: Mapping[str, Any], lat: Mapping[str, Any], where: str) -> str:
    run = next((r for r in index.get("latency") or [] if r["run_id"] == lat["run"]), None)
    if run is None:
        raise RecordError(f"{where}: readme latency run {lat['run']!r} is not a latency record")
    concurrency, stream = lat.get("concurrency", 1), lat.get("stream", False)
    cell = next(
        (c for c in run["cells"] if c["concurrency"] == concurrency and c["stream"] == stream),
        None,
    )
    if cell is None:
        raise RecordError(
            f"{where}: latency run {lat['run']!r} has no cell at concurrency {concurrency}, "
            f"stream {stream}"
        )
    o = cell["overhead_ms"]
    return (
        f"{lat['label']}: p50 {fmt_duration(o['p50'])}, p95 {fmt_duration(o['p95'])} "
        f"({cell['requests']} requests, {run['hardware']}; "
        f"[record](eval/results/runs/{run['run_id']}.json))."
    )


def _col_id(col: Mapping[str, Any]) -> str:
    return str(col.get("fixture_set") or col["dataset"])


def _pct(value: float | None) -> str:
    # Rounded as both tables in docs/benchmarks.md round (one decimal of the percentage).
    return _MISSING if value is None else f"{value * 100:.1f} %"


def _latest_counts(counts: Sequence[Mapping[str, Any]]) -> dict[tuple[str, str], Any]:
    latest: dict[tuple[str, str], Any] = {}
    for c in counts:  # oldest first, as load_counts returns them: the newest run wins
        latest[(c["dataset"], c["system"]["key"])] = c
    return latest


def _snapshot(index: Mapping[str, Any], fixture_set: str, system: str) -> Any:
    for s in index["snapshots"]:
        if s["fixture_set"] == fixture_set and s["system"] == system:
            return s
    return None


class _Cell:
    def __init__(
        self,
        value: float | None,
        docs: int | None,
        links: list[str],
        over: float | None = None,
        missing: Sequence[str] = (),
    ) -> None:
        self.value, self.docs, self.links, self.over = value, docs, links, over
        self.missing = list(missing)


def _cell(
    index: Mapping[str, Any],
    latest: Mapping[tuple[str, str], Any],
    col: Mapping[str, Any],
    system: str,
) -> _Cell:
    if "fixture_set" in col:
        snap = _snapshot(index, col["fixture_set"], system)
        if snap is None:
            return _Cell(None, None, [])
        links = [f"eval/results/runs/{run_id}.json" for run_id in snap["run_ids"]]
        return _Cell(
            snap["all"]["leak"],
            snap["all"]["documents"],
            links,
            snap["all"].get("over_masking"),
            snap.get("missing_languages") or (),
        )
    c = latest.get((col["dataset"], system))
    if c is None:
        return _Cell(None, None, [])
    summary = c["summary"]
    over = summary.get("over_masking")
    return _Cell(
        summary["leak"]["value"],
        summary["documents"],
        [f"eval/datasets/results/{c['run_id']}.json"],
        over.get("value") if isinstance(over, Mapping) else None,
    )


def _header(index: Mapping[str, Any], col: Mapping[str, Any], cells: Sequence[_Cell]) -> str:
    if "fixture_set" in col:
        info = index["fixture_sets"].get(col["fixture_set"])
        if info is None:
            return str(col["title"])
        langs = "+".join(info["documents"])
        return f"{col['title']} ({langs}, {sum(info['documents'].values())} docs)"
    docs = next((c.docs for c in cells if c.docs is not None), None)
    return f"{col['title']} ({docs})" if docs is not None else str(col["title"])


def _escape(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def render_block(
    index: Mapping[str, Any], counts: Sequence[Mapping[str, Any]], spec: Mapping[str, Any]
) -> str:
    """The text between the markers (without them): a pure function of its inputs."""
    columns, rows = spec["columns"], spec["rows"]
    latest = _latest_counts(counts)
    grid = [[_cell(index, latest, col, row["system"]) for col in columns] for row in rows]
    headers = [_header(index, col, [g[j] for g in grid]) for j, col in enumerate(columns)]
    out = [_NOTE, "", *_table("Leak", headers, rows, columns, grid, "value"), ""]

    partial = sorted(
        {
            (rows[i].get("short", rows[i]["label"]), str(col["title"]), ", ".join(c.missing))
            for i, r in enumerate(grid)
            for j, (col, c) in enumerate(zip(columns, r, strict=True))
            if c.missing and c.value is not None
        },
        key=lambda t: (t[1], t[0]),
    )
    if partial:
        out.append(
            f"{_PARTIAL} Run on fewer languages than the set has, on an earlier version of its "
            "files, so not comparable with the complete rows: "
            + "; ".join(f"{who} on {where} (no {langs})" for who, where, langs in partial)
            + ". Per-language numbers are in [docs/benchmarks.md](docs/benchmarks.md)."
        )
        out.append("")

    p50 = []
    for row in rows:
        if row.get("p50", True) is False:
            continue
        for col in columns:
            if "fixture_set" not in col or col["fixture_set"] != index.get("headline_set"):
                continue
            snap = _snapshot(index, col["fixture_set"], row["system"])
            if snap is not None and snap["all"]["detect_p50_ms"] is not None:
                star = "*" if snap["all"]["latency_pooled"] else ""
                short = row.get("short", row["label"])
                p50.append(f"{short} {fmt_duration(snap['all']['detect_p50_ms'])}{star}")
            break
    if p50:
        out.append(
            f"Detection p50 on the `{index.get('headline_set')}` set: "
            + ", ".join(p50)
            + " (`*` averaged over several runs), each on the machine in its run record: "
            "compare loosely."
        )
        out.append("")

    first = rows[0]
    if spec.get("per_language"):
        headline = index.get("headline_set")
        snap = _snapshot(index, headline, first["system"]) if headline else None
        langs = (snap or {}).get("languages") or {}
        if isinstance(langs, Mapping) and langs:
            parts = [f"{lang} {_pct(m.get('leak'))}" for lang, m in sorted(langs.items())]
            out.append(
                f"Leak per language of the {first.get('short', first['label'])} row on "
                f"`{headline}`: " + ", ".join(parts) + "."
            )
            out.append("")

    if spec.get("latency"):
        out.append(_latency_line(index, spec["latency"], "docs/benchmarks/config.json"))
        out.append("")
    if spec.get("model_latency"):
        out.append(_model_latency_line(spec["model_latency"], "docs/benchmarks/config.json"))
        out.append("")

    if spec.get("over_masking_table"):
        out.extend(_table("Over-masking", headers, rows, columns, grid, "over"))
        out.append("")
        out.append(
            "Over-masking: share of masked spans that are not personal data; lower is better "
            "([how it is scored](docs/benchmarks.md#how-to-read-this))."
        )
        out.append("")
    overs = (
        []
        if spec.get("over_masking_table")
        else [
            f"{col['title']} {_pct(grid[0][j].over)}"
            for j, col in enumerate(columns)
            if grid[0][j].over is not None
        ]
    )
    if overs:
        out.append(
            f"Over-masking of the {first.get('short', first['label'])} row: "
            + ", ".join(overs)
            + " (share of masked spans that are not personal data; "
            "[how it is scored](docs/benchmarks.md#how-to-read-this))."
        )
        out.append("")

    refs = []
    for j, col in enumerate(columns):
        links = grid[0][j].links
        if len(links) == 1:
            refs.append(f"[{col['title']}]({links[0]})")
        elif links:
            refs.append(
                f"{col['title']} ("
                + " · ".join(f"[{k}]({link})" for k, link in enumerate(links, 1))
                + ")"
            )
    if refs:
        out.append(
            f"Records behind the {first.get('short', first['label'])} row: "
            + ", ".join(refs)
            + "; every other cell is in the [run log](docs/benchmarks.md#run-log)"
            + (
                " and [eval/datasets/results/](eval/datasets/results/)."
                if any("dataset" in col for col in columns)
                else "."
            )
        )
    return "\n".join(out) + "\n"


def _table(
    title: str,
    headers: Sequence[str],
    rows: Sequence[Mapping[str, Any]],
    columns: Sequence[Mapping[str, Any]],
    grid: Sequence[Sequence[_Cell]],
    attr: str,
) -> list[str]:
    """One markdown table of ``attr`` (``value`` = leak, ``over``); the lowest is bold."""
    body: list[list[str]] = [[str(row["label"])] for row in rows]
    for j, col in enumerate(columns):
        cid = _col_id(col)
        cells = [grid[i][j] for i in range(len(rows))]
        shown = [_pct(getattr(c, attr)) for c in cells]
        marks = []
        for row, c, text in zip(rows, cells, shown, strict=True):
            # A caveat mark explains a number: none on an empty cell or on the over-masking table.
            mark = (
                [str(row.get("marks", {}).get(cid, ""))]
                if attr == "value" and text != _MISSING
                else []
            )
            if c.missing and text != _MISSING:
                mark.append(_PARTIAL)
            marks.append(" ".join(m for m in mark if m))
        numbers = [float(s[:-2]) for s in shown if s != _MISSING]
        best = min(numbers) if numbers else None
        winners = [i for i, s in enumerate(shown) if s != _MISSING and float(s[:-2]) == best]
        bold = bool(winners) and not any(marks[i] for i in winners)
        for i, text in enumerate(shown):
            cell = f"**{text}**" if bold and i in winners else text
            body[i].append(cell + (f" {marks[i]}" if marks[i] else ""))
    return [
        "| " + " | ".join(_escape(h) for h in [title, *headers]) + " |",
        "|---|" + "---:|" * len(columns),
        *("| " + " | ".join(_escape(c) for c in r) + " |" for r in body),
    ]


def splice(
    doc: str, block: str, where: str, *, start_mark: str = START, end_mark: str = END
) -> str:
    """``doc`` with the text between the two markers replaced by ``block``."""
    start, end = doc.find(start_mark), doc.find(end_mark)
    if start < 0 or end < start or doc.count(start_mark) != 1 or doc.count(end_mark) != 1:
        raise RecordError(f"{where}: needs exactly one {start_mark} ... {end_mark} block")
    return doc[: start + len(start_mark)] + "\n" + block + doc[end:]


# --- LAB-1663: the compact layout and the intro block -------------------------------------

_LANGS = {"de": "German", "en": "English", "hu": "Hungarian", "pl": "Polish"}
_FIELD = re.compile(r"\{(leak|over|partial|docs|langs|codes):([^{}]+)\}")
_METRIC = {"leak": "leak", "over": "over_masking", "partial": "partial_leak"}


def _system(spec: Mapping[str, Any], name: str) -> str:
    return str((spec.get("aliases") or {}).get(name, name))


def _set_info(index: Mapping[str, Any], fixture_set: str, where: str) -> Mapping[str, Any]:
    info = index["fixture_sets"].get(fixture_set)
    if info is None:
        raise RecordError(f"{where}: no fixture set {fixture_set!r}")
    return info  # type: ignore[no-any-return]


def _language_names(codes: Sequence[str]) -> str:
    names = [_LANGS.get(c, c) for c in codes]
    return names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]


def fill(template: str, index: Mapping[str, Any], spec: Mapping[str, Any], where: str) -> str:
    """``template`` with every ``{field:set[:system]}`` replaced from the records."""

    def one(m: re.Match[str]) -> str:
        field, arg = m.group(1), m.group(2)
        fixture_set, _, system = arg.partition(":")
        info = _set_info(index, fixture_set, where)
        if field == "docs":
            return str(sum(info["documents"].values()))
        if field in ("langs", "codes"):
            codes = list(info["documents"])
            return _language_names(codes) if field == "langs" else ", ".join(codes)
        key = _system(spec, system)
        snap = _snapshot(index, fixture_set, key)
        value = None if snap is None else snap["all"].get(_METRIC[field])
        if value is None:
            raise RecordError(f"{where}: no {field} for {key!r} on {fixture_set!r} ({m.group(0)})")
        if snap.get("missing_languages"):
            raise RecordError(f"{where}: {key!r} on {fixture_set!r} misses languages")
        return _pct(value)

    return _FIELD.sub(one, template)


def _bold_min(values: Sequence[float | None]) -> list[str]:
    shown = [_pct(v) for v in values]
    nums = [float(t[:-2]) for t in shown if t != _MISSING]
    best = min(nums) if nums else None
    return [f"**{t}**" if t != _MISSING and float(t[:-2]) == best else t for t in shown]


def render_compact(
    index: Mapping[str, Any], spec: Mapping[str, Any], where: str = "docs/benchmarks/config.json"
) -> str:
    """The compact results block: one ``set x system`` table, notes, caveats, details."""
    columns, rows = spec["columns"], spec["rows"]
    out = [_NOTE, ""]
    head = ["Leak · over-masking", *(str(r.get("short", r["label"])) for r in rows)]
    out.append("| " + " | ".join(_escape(h) for h in head) + " |")
    out.append("|---|" + "---:|" * len(rows))
    for col in columns:
        fs = col["fixture_set"]
        info = _set_info(index, fs, where)
        cells = []
        for r in rows:
            snap = _snapshot(index, fs, r["system"])
            if snap is not None and snap.get("missing_languages"):
                raise RecordError(f"{where}: {r['system']!r} on {fs!r} misses languages")
            cells.append(snap["all"] if snap else {})
        leaks = _bold_min([c.get("leak") for c in cells])
        overs = _bold_min([c.get("over_masking") for c in cells])
        docs = sum(info["documents"].values())
        label = f"{col['title']} · {docs} docs ({'+'.join(info['documents'])})"
        # No breakable space inside a cell, so a row never wraps at GitHub's 1280 px column.
        body = [
            f"{a}&nbsp;·&nbsp;{b}".replace(" %", "%") for a, b in zip(leaks, overs, strict=True)
        ]
        out.append("| " + " | ".join(_escape(c) for c in [label, *body]) + " |")
    out.append("")
    for note in spec.get("notes") or []:
        out.extend([fill(note, index, spec, where), ""])
    caveats = spec.get("caveats") or []
    if caveats:
        out.append("**Caveats**")
        out.append("")
        out.extend(f"- {fill(c, index, spec, where)}" for c in caveats)
        out.append("")
    details = spec.get("details") or {}
    lines = [fill(x, index, spec, where) for x in details.get("lines") or []]
    if spec.get("model_latency"):
        lines.append(_model_latency_line(spec["model_latency"], where))
    first = rows[0]
    refs = []
    for col in columns:
        snap = _snapshot(index, col["fixture_set"], first["system"])
        if snap is None:
            continue
        links = [f"eval/results/runs/{run_id}.json" for run_id in snap["run_ids"]]
        if len(links) == 1:
            refs.append(f"[{col['title']}]({links[0]})")
        else:
            refs.append(
                f"{col['title']} ("
                + " · ".join(f"[{k}]({link})" for k, link in enumerate(links, 1))
                + ")"
            )
    if refs:
        lines.append(
            f"Records behind the {first['label']} column: "
            + ", ".join(refs)
            + "; every other cell is in the [run log](docs/benchmarks.md#run-log)."
        )
    if lines:
        out.append(f"<details><summary>{details.get('summary', 'How this is measured')}</summary>")
        out.append("")
        for line in lines:
            out.extend([line, ""])
        out.append("</details>")
    return "\n".join(out) + "\n"


def render_intro(
    index: Mapping[str, Any], spec: Mapping[str, Any], where: str = "docs/benchmarks/config.json"
) -> str:
    """The first-screen block: the pitch bullets, then the hero image in light and dark."""
    intro = spec["intro"]
    img = f"docs/benchmarks/{intro['image']}"
    alt = fill(intro["alt"], index, spec, where).replace('"', "&quot;")
    out = [
        "<!-- Generated by `pii-guard eval report` from the run records and the `readme.intro` "
        "section of docs/benchmarks/config.json; edit those, not this block. -->",
        "",
        *(f"- {fill(b, index, spec, where)}" for b in intro["bullets"]),
        "",
        "<picture>",
        f'  <source media="(prefers-color-scheme: dark)" srcset="{img}-dark.svg">',
        f'  <img src="{img}.svg" alt="{alt}" width="100%">',
        "</picture>",
        "",
        f'<p align="center"><sub>{fill(intro["caption"], index, spec, where)}</sub></p>',
    ]
    return "\n".join(out) + "\n"


def render_readme(
    doc: str,
    index: Mapping[str, Any],
    counts: Sequence[Mapping[str, Any]],
    spec: Mapping[str, Any],
    where: str,
) -> str:
    """``doc`` (the README) with its generated blocks rebuilt."""
    if spec.get("layout") == "compact":
        block = render_compact(index, spec)
    else:
        block = render_block(index, counts, spec)
    doc = splice(doc, block, where)
    if spec.get("intro"):
        doc = splice(
            doc, render_intro(index, spec), where, start_mark=INTRO_START, end_mark=INTRO_END
        )
    return doc
